-- PakThai Tech test-data cleanup; backup first, then remove confirmed test IDs only.
CREATE TABLE IF NOT EXISTS backup_test_cleanup_20261009_buyers AS SELECT * FROM buyers WHERE id IN (1,2);
CREATE TABLE IF NOT EXISTS backup_test_cleanup_20261009_sellers AS SELECT * FROM sellers WHERE id IN (1,2);
CREATE TABLE IF NOT EXISTS backup_test_cleanup_20261009_requirements AS SELECT * FROM buyer_requirements WHERE buyer_id IN (1,2);
CREATE TABLE IF NOT EXISTS backup_test_cleanup_20261009_matches AS SELECT * FROM buyer_matches WHERE buyer_id IN (1,2) OR seller_id IN (1,2);
CREATE TABLE IF NOT EXISTS backup_test_cleanup_20261009_opportunities AS SELECT * FROM opportunities WHERE seller_id IN (1,2) OR notes LIKE '%Test Pakistan Buyer%';
CREATE TABLE IF NOT EXISTS backup_test_cleanup_20261009_seller_offers AS SELECT * FROM seller_offers WHERE seller_id IN (1,2);
CREATE TABLE IF NOT EXISTS backup_test_cleanup_20261009_supplier_offers AS SELECT * FROM supplier_offers WHERE seller_id IN (1,2);
CREATE TABLE IF NOT EXISTS backup_test_cleanup_20261009_seller_history AS SELECT * FROM seller_history WHERE seller_id IN (1,2);
CREATE TABLE IF NOT EXISTS backup_test_cleanup_20261009_negotiations AS SELECT * FROM negotiations WHERE seller_id IN (1,2) OR opportunity_id IN (SELECT id FROM opportunities WHERE seller_id IN (1,2) OR notes LIKE '%Test Pakistan Buyer%') OR buyer_match_id IN (SELECT id FROM buyer_matches WHERE buyer_id IN (1,2) OR seller_id IN (1,2));
CREATE TABLE IF NOT EXISTS backup_test_cleanup_20261009_purchase_tracking AS SELECT * FROM purchase_tracking WHERE seller_id IN (1,2) OR opportunity_id IN (SELECT id FROM opportunities WHERE seller_id IN (1,2) OR notes LIKE '%Test Pakistan Buyer%');
CREATE TABLE IF NOT EXISTS backup_test_cleanup_20261009_customer_requests AS SELECT * FROM customer_requests WHERE buyer_id IN (1,2) OR requirement_id IN (SELECT id FROM buyer_requirements WHERE buyer_id IN (1,2));
CREATE TABLE IF NOT EXISTS backup_test_cleanup_20261009_quotations AS SELECT * FROM quotations WHERE buyer_id IN (1,2) OR opportunity_id IN (SELECT id FROM opportunities WHERE seller_id IN (1,2) OR notes LIKE '%Test Pakistan Buyer%');
CREATE TABLE IF NOT EXISTS backup_test_cleanup_20261009_orders AS SELECT * FROM orders WHERE buyer_id IN (1,2) OR opportunity_id IN (SELECT id FROM opportunities WHERE seller_id IN (1,2) OR notes LIKE '%Test Pakistan Buyer%');
CREATE TABLE IF NOT EXISTS backup_test_cleanup_20261009_owner_approvals AS SELECT * FROM owner_approvals WHERE opportunity_id IN (SELECT id FROM opportunities WHERE seller_id IN (1,2) OR notes LIKE '%Test Pakistan Buyer%');
DELETE FROM owner_approvals WHERE opportunity_id IN (SELECT id FROM opportunities WHERE seller_id IN (1,2) OR notes LIKE '%Test Pakistan Buyer%');
DELETE FROM purchase_tracking WHERE seller_id IN (1,2) OR opportunity_id IN (SELECT id FROM opportunities WHERE seller_id IN (1,2) OR notes LIKE '%Test Pakistan Buyer%');
DELETE FROM negotiations WHERE seller_id IN (1,2) OR opportunity_id IN (SELECT id FROM opportunities WHERE seller_id IN (1,2) OR notes LIKE '%Test Pakistan Buyer%') OR buyer_match_id IN (SELECT id FROM buyer_matches WHERE buyer_id IN (1,2) OR seller_id IN (1,2));
DELETE FROM customer_requests WHERE buyer_id IN (1,2) OR requirement_id IN (SELECT id FROM buyer_requirements WHERE buyer_id IN (1,2));
DELETE FROM quotations WHERE buyer_id IN (1,2) OR opportunity_id IN (SELECT id FROM opportunities WHERE seller_id IN (1,2) OR notes LIKE '%Test Pakistan Buyer%');
DELETE FROM orders WHERE buyer_id IN (1,2) OR opportunity_id IN (SELECT id FROM opportunities WHERE seller_id IN (1,2) OR notes LIKE '%Test Pakistan Buyer%');
DELETE FROM seller_history WHERE seller_id IN (1,2);
DELETE FROM supplier_offers WHERE seller_id IN (1,2);
DELETE FROM seller_offers WHERE seller_id IN (1,2);
DELETE FROM buyer_matches WHERE buyer_id IN (1,2) OR seller_id IN (1,2);
DELETE FROM buyer_requirements WHERE buyer_id IN (1,2);
